using System;using System.IO;using System.Xml;using System.Text;
namespace BeamScheduleFormatter {
sealed class PowProjectSnapshot {internal XmlDocument Document;internal PowSourceFiles Sources;internal bool SourcesDeferred;}
static class PowProjectFileWriter {
 internal static void AtomicWrite(string path,string xml){AtomicWrite(path,output=>{byte[] bytes=new UTF8Encoding(false).GetBytes(xml);output.Write(bytes,0,bytes.Length);});}
 internal static void AtomicWrite(string path,Action<Stream> write){AtomicWrite(path,write,null);}
 internal static void AtomicWrite(string path,Action<Stream> write,Action<string> verify){string full=Path.GetFullPath(path),temp=full+"."+Guid.NewGuid().ToString("N")+".tmp";try{using(var output=new FileStream(temp,FileMode.CreateNew,FileAccess.Write,FileShare.None)){write(output);output.Flush(true);}/* the written file is checked before it replaces the project (owner, 17 Nov 2026) */if(verify!=null)verify(temp);if(File.Exists(full))File.Replace(temp,full,null);else File.Move(temp,full);}finally{if(File.Exists(temp))File.Delete(temp);}}
 internal static void WriteWithSources(string path,string snapshot,PowSourceFiles sources){var doc=new XmlDocument{XmlResolver=null};doc.LoadXml(snapshot);if(doc.DocumentElement["SourceFiles"]!=null)throw new Exception("Project snapshot already contains attachment payloads.");AtomicWrite(path,output=>{using(var writer=XmlWriter.Create(output,new XmlWriterSettings{Encoding=new UTF8Encoding(false),CloseOutput=false})){writer.WriteStartDocument();writer.WriteStartElement(doc.DocumentElement.Name);foreach(XmlAttribute a in doc.DocumentElement.Attributes)a.WriteTo(writer);foreach(XmlNode node in doc.DocumentElement.ChildNodes)node.WriteTo(writer);sources.WriteStreaming(writer);writer.WriteEndElement();writer.WriteEndDocument();}},written=>{int expected=PowBackups.Entries(snapshot);var check=Read(written,true);if(check.Document.DocumentElement==null||PowBackups.EntriesInFile(written)!=expected)throw new Exception("The saved file could not be verified; the project file was not replaced.");});}
 internal static PowProjectSnapshot Read(string path){return Read(path,false);}
 /* deferSources: the embedded source archive is skipped here and read later with ReadSources (owner: opening took ~22 s). */
 internal static PowProjectSnapshot Read(string path,bool deferSources){using(var input=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read))using(var reader=XmlReader.Create(input,new XmlReaderSettings{XmlResolver=null,DtdProcessing=DtdProcessing.Prohibit,MaxCharactersInDocument=0,IgnoreWhitespace=true})){reader.MoveToContent();if(reader.NodeType!=XmlNodeType.Element)throw new Exception("Choose a Program of Works file.");var doc=new XmlDocument{XmlResolver=null};var root=doc.CreateElement(reader.Name);if(reader.MoveToFirstAttribute()){do{root.SetAttribute(reader.Name,reader.Value);}while(reader.MoveToNextAttribute());reader.MoveToElement();}doc.AppendChild(root);bool empty=reader.IsEmptyElement,hasArchive=false;var sources=new PowSourceFiles();reader.ReadStartElement();if(!empty){while(reader.MoveToContent()!=XmlNodeType.EndElement){if(reader.EOF)throw new Exception("Incomplete Program of Works file.");if(reader.NodeType==XmlNodeType.Element&&reader.Name=="SourceFiles"){if(hasArchive)throw new Exception("Duplicate project source archive.");if(deferSources)reader.Skip();else sources=PowSourceFiles.ReadArchive(reader,false);/* verified in the background after the project opens */hasArchive=true;}else{var node=doc.ReadNode(reader);if(node!=null)root.AppendChild(node);}}reader.ReadEndElement();}if(reader.MoveToContent()!=XmlNodeType.None)throw new Exception("Unexpected content after Program of Works.");if(!deferSources)PowSourceFiles.ValidateManifest(root,sources,hasArchive);else if(!hasArchive)PowSourceFiles.ValidateManifest(root,sources,false);return new PowProjectSnapshot{Document=doc,Sources=sources,SourcesDeferred=deferSources&&hasArchive};}}
 internal static PowSourceFiles ReadSources(string path){using(var input=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read))using(var reader=XmlReader.Create(input,new XmlReaderSettings{XmlResolver=null,DtdProcessing=DtdProcessing.Prohibit,MaxCharactersInDocument=0,IgnoreWhitespace=true})){reader.MoveToContent();if(reader.IsEmptyElement)return new PowSourceFiles();reader.ReadStartElement();while(reader.MoveToContent()==XmlNodeType.Element){if(reader.Name=="SourceFiles")return PowSourceFiles.ReadArchive(reader,false);reader.Skip();}return new PowSourceFiles();}}
}
}
